<?php
require_once __DIR__.'/../includes/auth.php';requireLogin();$u=currentUser();$errors=[];
if(isPost()){verifyCsrf();$name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$nameLength=mb_strlen($name);if($nameLength<3||$nameLength>100)$errors[]='يجب أن يكون الاسم بين 3 و100 حرف.';if(mb_strlen($email)>191||!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='البريد غير صالح.';$s=db()->prepare('SELECT id FROM users WHERE email=? AND id<>?');$s->execute([$email,$u['id']]);if($s->fetch())$errors[]='البريد مستخدم بالفعل.';$new=(string)($_POST['new_password']??'');if($new!==''){ $s=db()->prepare('SELECT password FROM users WHERE id=?');$s->execute([$u['id']]);if(!password_verify((string)($_POST['current_password']??''),$s->fetchColumn()))$errors[]='كلمة المرور الحالية غير صحيحة.';if(strlen($new)<8||strlen($new)>4096)$errors[]='يجب أن تكون كلمة المرور الجديدة بين 8 و4096 حرف.';if($new!==($_POST['confirm_password']??''))$errors[]='تأكيد كلمة المرور غير مطابق.';}if(!$errors){if($new!=='')db()->prepare('UPDATE users SET name=?,email=?,password=?,updated_at=NOW() WHERE id=?')->execute([$name,$email,password_hash($new,PASSWORD_DEFAULT),$u['id']]);else db()->prepare('UPDATE users SET name=?,email=?,updated_at=NOW() WHERE id=?')->execute([$name,$email,$u['id']]);flash('success','تم تحديث الملف الشخصي.');redirect(url('admin/profile.php'));}}
$pageTitle='الملف الشخصي';require __DIR__.'/includes/header.php';?><div class="card stat-card mx-auto" style="max-width:750px"><div class="card-body p-4"><h5 class="fw-bold mb-4">بيانات الحساب</h5><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><div class="row"><div class="col-md-6 mb-3"><label class="form-label">الاسم</label><input class="form-control" name="name" required value="<?=e($_POST['name']??$u['name'])?>"></div><div class="col-md-6 mb-3"><label class="form-label">البريد</label><input class="form-control" type="email" name="email" required value="<?=e($_POST['email']??$u['email'])?>"></div></div><hr><p class="fw-bold">تغيير كلمة المرور <small class="text-secondary fw-normal">(اختياري)</small></p><input class="form-control mb-3" type="password" name="current_password" placeholder="كلمة المرور الحالية"><input class="form-control mb-3" type="password" name="new_password" placeholder="كلمة المرور الجديدة"><input class="form-control mb-4" type="password" name="confirm_password" placeholder="تأكيد الجديدة"><button class="btn btn-primary">حفظ التغييرات</button></form></div></div><?php require __DIR__.'/includes/footer.php';?>
